head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.file_flag = "N";
scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyLstBzProcsNo = "", scwin.strKeyIsurCd = "";
scwin.contnId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const arr = new Array();
        await scwin.searchCode();
        scwin.fn_GetPar = $c.frame.path("../").scwin.fn_GetPar;
        scwin.fn_SetPar = $c.frame.path("../").scwin.fn_SetPar;
        if (scwin.fn_GetPar !== undefined) {
            scwin.fn_GetPar(arr);
        }
        /*
        arr[0] = "03929";
        arr[1] = "920";
        arr[2] = "시험발행기관명";
         */

        panel_Term.hide();
        txb_IsurCd.setValue((arr.length >= 1 ? arr[0] : ""));
        scwin.strKeyIsurCd = (arr.length >= 1 ? arr[0] : "");
        scwin.strKeyLstBzProcsNo = (arr.length >= 2 ? arr[1] : "");
        txb_CoNm.setValue((arr.length >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

        if (arr.length > 2) {
            await scwin.search();
        }
        scwin.setDataHeader();
        scwin.setFornListCntrNm();
        await scwin.searchIssue();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07108.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Cmt_OnLoadCompleted
 * @description dts_Cmt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cmt_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            scwin.setKeyCtrOnUpd(); // 조회직후에는 수정상태
            await scwin.searchReqInf();
            // fn_fileSearch();
            await scwin.read();
        }
        /*
        fn_setPanReadOnlyOnLoad(dts_Cmt, pan_Cmt);
        med_ComiteDd.readOnly = true;
         */
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07108.dts_Cmt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Cmt_OnRowPosChanged
 * @description Cmt On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Cmt_OnRowPosChanged = async function(row) {
    try {
        if (dts_Cmt.getRowCount() > 0) {
            if (dts_Cmt.getCellData(row, "BZ_PROCS_NO") !== "") {
                await scwin.searchReqInf();
            }

            // alert("fn_fileSearch");
            // fn_fileSearch();
            await scwin.read();
            scwin.setFornListCntrNm();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07108.dts_Cmt_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_ReqInf_OnLoadCompleted
 * @description dts_ReqInf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_ReqInf.getCellData('1', 'SECUGRP_ID2') === '1' || dts_ReqInf.getCellData('1', 'SECUGRP_ID3') === '1') {
            pan_Forn.show("");
        } else {
            pan_Forn.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07108.dts_ReqInf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name tr_Save_OnFail
 * @description tr Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnFail = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_FAIL);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07108.tr_Save_OnFail" });
    }
};

/**
 * @method
 * @name tr_Save_OnSuccess
 * @description tr Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Save_OnSuccess = async function() {
    try {
        await $c.win.alert(scwin.MSG_TR_DOME);
        await scwin.search();
        scwin.parentRefresh();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07108.tr_Save_OnSuccess" });
    }
};

