/**
 * @method
 * @name dts_fileList_OnLoadCompleted
 * @description dts_fileList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_fileList_OnLoadCompleted = function(rowcount) {
    try {
        const setArr = [txb_file_name, txb_file_name2];
        // var setBtn = [btn_lineadd,btn_lineadd2,btn_lineadd3,btn_lineadd4];
        if (rowcount > 0) {
            let k;
            for (let i = 0; i < rowcount; i++) {
                k = dts_fileList.getCellData(i + 1, "SEQ");
                if (k >= '3') {
                    continue;
                }
                setArr[k - 1].setValue(dts_fileList.getCellData(i + 1, "filename"));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07108.dts_fileList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_fileList_OnLoadError
