/**
 * @method
 * @name save
 * @description search function end
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(jobType) {
    {
        /*
        var s = "";
        for (i = 1; i <= dts_ReqInf.CountColumn; i++) { s = s + "\n" +  dts_ReqInf.ColumnID(i) + "," + dts_ReqInf.ColumnString(1, i); }
        log.Text = log.Text + "\n" + s + "\n" + dts_ReqInf.Text;

        s = "";
        for (i = 1; i <= dts_Cmt.CountColumn; i++) { s = s + "\n" +  dts_Cmt.ColumnID(i) + "," + dts_Cmt.ColumnString(1, i); }
        log.Text = log.Text + "\n" + s + "\n" + dts_Cmt.Text;
         */
    }

    /*
    if (js_dep_cd.substring(0, 2) !== '33') { //코스닥 심사팀
    	alert("해당 부서만 접수가 가능합니다."); return;
    }
     */

    // 2009.05.12 위원회일/철회일 필수 체크
    if (med_ComiteDd.getValue() === "") {
        await $c.win.alert("위원회일/철회일을 입력하여 주세요");
        med_ComiteDd.focus();
        return false;
    }
    const check = scwin.fileYnCheck();
    let vScrenProcTpCd;
    if (jobType === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (jobType === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (jobType === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    if ($c.cp.isModified(dts_Cmt) || $c.cp.isModified(dts_ReqInf)) {
        // dts_ReqInf의 UseChangeInfo를 false로 지정하여 무조건 insert상태로 서버로 전송됨.
        dts_ReqInf.setCellData(1, "LST_COMITE_RSLT_SAVE_EMP_NO", scwin.getUserId());
        tr_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_tr_Save",
            action : "/prelistingKosdaq.do",
            ref : "dts_ReqInf,dts_Cmt,dts_fileList",
            target : "tr_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } else if (!$c.cp.isModified(dts_Cmt) && !$c.cp.isModified(dts_ReqInf) && check === "Y") {
        await scwin.fileInsert();
    } else {
        await $c.win.alert(scwin.MGS_NO_UPDT);
    }
};

/**
 * @method
 * @name fileInsert
 * @description 첨부파일 저장
 * @returns {Promise<void>}
