 */
scwin.fileInsert = async function() {
    if ($c.cp.isModified(dts_fileList)) {
        // alert(dts_fileList.Text);
        const sbmOptions = {
            id : "sbm_tr_File",
            action : "/prelistingKosdaq.do",
            ref : "dts_fileList",
            target : "tr_File=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

