 * @description get User Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getUserId = function() {
    return js_emp_no;
};

/**
 * @method
 * @name fileYnCheck
 * @description 파일첨부 삭제 여부
 * @returns {void}
 * @hidden N
 */
scwin.fileYnCheck = function() {
    for (i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") !== "") {
            scwin.file_flag = "Y";
        }
    }
    return scwin.file_flag;
};
