/**
 * @method
 * @name txbLoad
 * @description txb Load 처리
 * @returns {void}
 * @hidden N
 */
scwin.txbLoad = function() {
    const txbArr = [txb_file_name, txb_file_name2];
    for (let i = 0; i < txbArr.length; i++) {
        txbArr[i].setValue("");
    }
};

/**
 * @method
 * @name addNewCmt
 * @description add New Cmt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.addNewCmt = async function() {
    dts_Cmt.insertRow();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "BZ_PROCS_NO", scwin.strKeyLstBzProcsNo);
    await scwin.searchReqInf();

    // fn_setPanWritableOnAdd(pan_Cmt);
    scwin.setKeyCtrOnAdd(); // 추가상태에서는  key컬럼수정가능
    scwin.txbLoad();
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_FST_LIST_CNTR_CD", '');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_COM_SCND_LIST_CNTR_CD", '');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_FST_LIST_MISC_CNTR_NM", '');
    dts_Cmt.setCellData(dts_Cmt.getRowPosition(), "FORN_SCND_LIST_MISC_CNTR_NM", '');
    scwin.setFornListCntrNm();
};

/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRow = async function() {
    dts_Cmt.removeRow(dts_Cmt.getRowPosition());
    await scwin.save("D");
};

